def find_path(graph, start, goal):
    # This function uses the Depth-First Search (DFS) algorithm to find a path from start to goal in the graph
    stack = [(start, [start])]  # Initialize stack with (current node, path to reach this node)

    while stack:
        (node, path) = stack.pop()

        if node not in graph:
            continue  # If node is not in graph, ignore it

        if node == goal:
            return path  # If the node is the goal, return the path

        for neighbor in graph[node]:
            if neighbor not in path:  # To avoid cycles, we only consider nodes not already in the current path
                stack.append((neighbor, path + [neighbor]))  # Push the neighbor and the extended path

    return None  # Return None if the goal is unreachable
