    # Initialize the path and visited nodes
    path = None
    visited = set()
    path_record = {start: None}  # for reconstruct the path after finding the goal

    # Use a set for efficient 'in' checks
    def depth_first_search(node):
        nonlocal path
        if node == goal:
            # If the goal is found, reconstruct the path
            path = []
            while node is not None:
                path.append(node)
                node = path_record[node]
            path.reverse()
            return True
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if depth_first_search(neighbor):
                path_record[neighbor] = node
                return True
        return False

    if depth_first_search(start):
        return path
    else:
